下面是一个用 Python 实现的最小堆（Min Heap）示例，支持 `insert` 和 `extract_min` 操作，并附带一些常用辅助方法（如 `peek_min`、`size` 等）。

```python
class MinHeap:
    def __init__(self):
        # 使用列表存储堆，索引从 0 开始
        self.heap = []

    def _parent(self, i):
        return (i - 1) // 2

    def _left_child(self, i):
        return 2 * i + 1

    def _right_child(self, i):
        return 2 * i + 2

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def _sift_up(self, i):
        """将索引 i 处的元素向上调整，维持最小堆性质"""
        while i > 0:
            parent = self._parent(i)
            if self.heap[i] < self.heap[parent]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _sift_down(self, i):
        """将索引 i 处的元素向下调整，维持最小堆性质"""
        n = len(self.heap)
        while True:
            left = self._left_child(i)
            right = self._right_child(i)
            smallest = i

            if left < n and self.heap[left] < self.heap[smallest]:
                smallest = left
            if right < n and self.heap[right] < self.heap[smallest]:
                smallest = right

            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break

    def insert(self, value):
        """插入元素"""
        self.heap.append(value)
        self._sift_up(len(self.heap) - 1)

    def extract_min(self):
        """取出并删除最小元素（堆顶）"""
        if not self.heap:
            raise IndexError("extract_min from empty heap")

        min_val = self.heap[0]
        last_val = self.heap.pop()

        if self.heap:
            self.heap[0] = last_val
            self._sift_down(0)

        return min_val

    def peek_min(self):
        """查看最小元素但不删除"""
        if not self.heap:
            raise IndexError("peek_min from empty heap")
        return self.heap[0]

    def size(self):
        return len(self.heap)

    def is_empty(self):
        return len(self.heap) == 0

    def __repr__(self):
        return f"MinHeap({self.heap})"


# 简单测试
if __name__ == "__main__":
    h = MinHeap()
    for x in [5, 3, 8, 1, 2]:
        h.insert(x)
        print("插入后:", h)

    print("最小元素:", h.peek_min())
    while not h.is_empty():
        print("取出最小:", h.extract_min())
```

说明要点：
- 使用列表 `self.heap` 存储堆，索引从 0 开始。
- `insert`：在末尾追加元素，然后调用 `_sift_up` 向上调整。
- `extract_min`：取出堆顶，将最后一个元素移到堆顶，然后调用 `_sift_down` 向下调整。
- 时间复杂度：
  - `insert`：O(log n)
  - `extract_min`：O(log n)
  - `peek_min`：O(1)

